/**
 * The recipes evaluated at a frame, exactly as the motion runtime evaluates the Motion IR they compile to: a tween's value is
 * `from + (to - from) * ease((frame - start) / duration)` (clamped to its window; keyframes take the tween's ease as their
 * playback ease and run linearly between offsets; `repeat` plays it again, `yoyo` backwards every other time), before its
 * start a tween shows its `from` when it renders immediately and the rest value otherwise, and of several tweens of one
 * property the latest that has started wins. `test/recipes-runtime.test.ts` asserts these values against the runtime itself.
 *
 * The editor draws from here: the live blend of a transition between two scene pictures (`sampleTransition`), the hover
 * thumbnails of the Transitions and Animations drawers (`sampleTransition`, `samplePreset`) and the CSS of a sampled look
 * (`lookCss`, the transform order of `runtime/geometry.ts`).
 */
import { localMatrix, quad, transformMatrix, type Matrix, type Point } from '../runtime/geometry'
import { presetTrackFields, type PresetAnimationTiming, type PresetTween } from './presets'
import { segmentTweenEase, type ResolvedTransition, type SegmentTarget, type SegmentTween, type TransitionRecipe } from './transitions'
import type { EaseResolver, Keyframes, Size } from './types'

/** How one element looks: offset (px), scales, rotation and skew (degrees), opacity (0-1), blur (px). */
export interface Look {
  x: number
  y: number
  scale: number
  scale_x: number
  scale_y: number
  rotation: number
  skew_x: number
  skew_y: number
  opacity: number
  blur: number
}

export const REST_LOOK: Readonly<Look> = Object.freeze({ x: 0, y: 0, scale: 1, scale_x: 1, scale_y: 1, rotation: 0, skew_x: 0, skew_y: 0, opacity: 1, blur: 0 })

const LOOK_PROPERTIES = Object.keys(REST_LOOK) as Array<keyof Look>

/** The rest value of an animatable property (the IR's defaults: scales and opacity 1, the rest 0). */
export function restValue(property: string): number {
  return property === 'scale' || property === 'scale_x' || property === 'scale_y' || property === 'opacity' ? 1 : 0
}

// ------------------------------------------------------------------ one tween, one property

/** One tween of a property on a frame axis (the fields of a Motion IR tween the value depends on). */
export interface SampleTrack {
  start: number
  /** Length of one play (frames). */
  duration: number
  ease: string
  /** GSAP immediateRender: before its start the tween shows its first value. */
  immediate: boolean
  from?: number
  to?: number
  keyframes?: Keyframes
  /** Extra plays (the IR `repeat`); `yoyo` plays every other one backwards. */
  repeat?: number
  yoyo?: boolean
}

function keyframeValue(frames: Keyframes, eased: number): number {
  const first = frames[0]
  if (!first) return 0
  const at = eased * 100
  if (at <= first.offset) return first.value
  for (let index = 1; index < frames.length; index += 1) {
    const previous = frames[index - 1] as { offset: number; value: number }
    const next = frames[index] as { offset: number; value: number }
    if (at <= next.offset) {
      const span = next.offset - previous.offset
      return span <= 0 ? next.value : previous.value + ((next.value - previous.value) * (at - previous.offset)) / span
    }
  }
  return (frames[frames.length - 1] as { value: number }).value
}

/** The tween's value at one point of a play (0-1), eased. */
function playValue(track: SampleTrack, progress: number, resolve: EaseResolver): number {
  const eased = resolve(track.ease)(progress)
  if (track.keyframes) return keyframeValue(track.keyframes, eased)
  const from = track.from ?? 0
  const to = track.to ?? from
  return from + (to - from) * eased
}

/** The value of a tween that has started (`frame >= start`): its play and the progress inside it, held after the end. */
function startedValue(track: SampleTrack, frame: number, resolve: EaseResolver): number {
  const plays = 1 + Math.max(0, track.repeat ?? 0)
  const local = frame - track.start
  if (track.duration <= 0) return playValue(track, track.yoyo && plays % 2 === 0 ? 0 : 1, resolve)
  const total = track.duration * plays
  const clamped = local >= total ? total : local
  let play = Math.floor(clamped / track.duration)
  let progress = (clamped - play * track.duration) / track.duration
  if (play >= plays) {
    play = plays - 1
    progress = 1
  }
  if (track.yoyo && play % 2 === 1) progress = 1 - progress
  return playValue(track, progress, resolve)
}

/**
 * The value a property shows at `frame`: until its first tween starts, that tween's first value when it renders immediately
 * and `rest` otherwise; then the latest tween that has started (held at its end value until the next one starts).
 */
export function sampleTracks(rest: number, tracks: readonly SampleTrack[], frame: number, resolve: EaseResolver): number {
  if (tracks.length === 0) return rest
  const sorted = [...tracks].sort((a, b) => a.start - b.start)
  let current: SampleTrack | null = null
  for (const track of sorted) if (frame >= track.start) current = track
  if (current) return startedValue(current, frame, resolve)
  const first = sorted[0] as SampleTrack
  return first.immediate ? playValue(first, 0, resolve) : rest
}

// ------------------------------------------------------------------ transitions

/** The window's visible part in canvas pixels: its four corners, clockwise from its top left. */
export type ClipPolygon = readonly [Point, Point, Point, Point]

export interface TransitionSample {
  /** Paint order, bottom first. */
  order: ReadonlyArray<'from' | 'to' | 'dip'>
  /** The outgoing and the incoming scene picture (a clipping window never moves the picture it reveals: see `clip`). */
  from: Look
  to: Look
  /** The incoming picture's visible part while `to` is a clipping window (`wipe`); null = the whole picture. */
  clip: ClipPolygon | null
  /** The colour layer (`dip_to_color`, `flash`); null for the other kinds. */
  dip: { color: string; opacity: number } | null
  /** Normalised transform origins of the two pictures, present only when a kind turns or scales one about another point. */
  origin?: { from: readonly [number, number]; to: readonly [number, number] }
}

/** A recipe tween as a track of the sampler. */
function trackOf(tween: SegmentTween, easing: ResolvedTransition['easing']): SampleTrack {
  const base = { start: tween.start, duration: tween.duration, ease: segmentTweenEase(tween, easing), immediate: tween.immediate }
  return 'keyframes' in tween ? { ...base, keyframes: tween.keyframes } : { ...base, from: tween.from, to: tween.to }
}

function lookOf(target: SegmentTarget, recipe: TransitionRecipe, easing: ResolvedTransition['easing'], frame: number, resolve: EaseResolver): Look {
  const rest = recipe.rest[target] ?? {}
  const look: Look = { ...REST_LOOK }
  for (const property of LOOK_PROPERTIES) {
    const tracks = recipe.tweens.filter((tween) => tween.target === target && tween.property === property).map((tween) => trackOf(tween, easing))
    const restAt = (rest as Partial<Record<string, number>>)[property] ?? restValue(property)
    look[property] = sampleTracks(restAt, tracks, frame, resolve)
  }
  return look
}

const CENTRE = [0.5, 0.5] as const

/**
 * A transition recipe at a frame of its segment document (`frame` on the same axis as the recipe's window): how the two scene
 * pictures and the colour layer look, as the runtime draws the segment the compiler builds from the same recipe.
 */
export function sampleTransition(recipe: TransitionRecipe, resolved: ResolvedTransition, canvas: Size, frame: number, resolve: EaseResolver): TransitionSample {
  const from = lookOf('from', recipe, resolved.easing, frame, resolve)
  let to = lookOf('to', recipe, resolved.easing, frame, resolve)
  let clip: ClipPolygon | null = null
  if (recipe.clip) {
    // The window (the `to` wrapper: the canvas, or the turned square of `clip_box`; origin at its centre) clips; its content
    // moves (and turns) against it so the picture stays where it is. The picture is drawn at rest, only the window's corners
    // matter.
    const box = recipe.clip_box ?? { x: 0, y: 0, width: canvas.width, height: canvas.height }
    clip = quad(localMatrix(box, recipe.origin?.to ?? CENTRE, to), box.width, box.height)
    to = { ...REST_LOOK }
  }
  const color = recipe.dip_fill ?? resolved.color
  const dip = recipe.order.includes('dip') && color !== null ? { color, opacity: lookOf('dip', recipe, resolved.easing, frame, resolve).opacity } : null
  return {
    order: [...recipe.order],
    from,
    to,
    clip,
    dip,
    ...(recipe.origin && !recipe.clip && { origin: { from: recipe.origin.from ?? CENTRE, to: recipe.origin.to ?? CENTRE } }),
  }
}

// ------------------------------------------------------------------ presets

/**
 * The values a preset's tweens give its layer's content at `frame` frames into the animation (0 = its first frame). `rest`
 * holds the content's rest values the IR defaults do not give: its rotation, and for a text its grapheme count (`reveal`
 * at rest shows every grapheme).
 */
export function samplePreset(
  tweens: readonly PresetTween[],
  animation: PresetAnimationTiming,
  frame: number,
  resolve: EaseResolver,
  rest: Partial<Record<string, number>> = {},
): Record<string, number> {
  const out: Record<string, number> = {}
  const byProperty = new Map<string, SampleTrack[]>()
  for (const step of tweens) {
    const fields = presetTrackFields(step, animation)
    const track: SampleTrack = {
      start: 0,
      duration: fields.duration_frames,
      ease: fields.ease,
      immediate: fields.immediate_render,
      ...('keyframes' in fields ? { keyframes: fields.keyframes } : { from: fields.from, to: fields.to }),
      ...(fields.repeat !== undefined && { repeat: fields.repeat }),
      ...(fields.yoyo === true && { yoyo: true }),
    }
    byProperty.set(fields.property, [...(byProperty.get(fields.property) ?? []), track])
  }
  for (const [property, tracks] of byProperty) out[property] = sampleTracks(rest[property] ?? restValue(property), tracks, frame, resolve)
  return out
}

// ------------------------------------------------------------------ CSS

const round = (value: number, digits: number): number => {
  const factor = 10 ** digits
  const rounded = Math.round(value * factor) / factor
  return Object.is(rounded, -0) ? 0 : rounded
}

/** The look's own transform (without placement or origin), in the runtime's order: translate, rotate, skew, scale. */
export function lookMatrix(look: Look): Matrix {
  return transformMatrix(look)
}

/**
 * The CSS of a look: the transform in the order of `transformMatrix` (`translate rotate skew scale`; rotate and skew only
 * when they are not 0), the opacity and a blur filter (empty when there is none).
 */
export function lookCss(look: Look): { transform: string; opacity: number; filter: string } {
  const parts = [`translate(${round(look.x, 3)}px, ${round(look.y, 3)}px)`]
  if (look.rotation !== 0) parts.push(`rotate(${round(look.rotation, 3)}deg)`)
  if (look.skew_x !== 0 || look.skew_y !== 0) parts.push(`skew(${round(look.skew_x, 3)}deg, ${round(look.skew_y, 3)}deg)`)
  const sx = round(look.scale * look.scale_x, 4)
  const sy = round(look.scale * look.scale_y, 4)
  parts.push(sx === sy ? `scale(${sx})` : `scale(${sx}, ${sy})`)
  return { transform: parts.join(' '), opacity: round(look.opacity, 4), filter: look.blur > 0 ? `blur(${round(look.blur, 3)}px)` : '' }
}
